jwt_builder_t *b = jwt_builder_new();              /* LibJWT */
jwt_builder_setkey(b, JWT_ALG_RS256, signing_key); /* JWK, not raw PEM */
jwt_value_t v;
jwt_set_SET_STR(&v, "sub", subject);
jwt_builder_claim_set(b, &v);
jwt_set_SET_STR(&v, "aud", audience);
jwt_builder_claim_set(b, &v);
jwt_builder_time_offset(b, JWT_CLAIM_EXP, 300);
char *token = jwt_builder_generate(b);             /* caller owns token */
free(token);
jwt_builder_free(b);
